arguments.command:
cd /tmp/sv-56136c935cd84ead8f6af4ddf8fc8bb0 && \
# These offsets might be in the thunk region which redirects to actual code. 
# Let's try using DWARF info differently - use objdump to disassemble around those addresses
# Actually let's look at ALL symbols (not just FUNC type) near these addresses
readelf -sW libmonosgen-2.0.so.dbg 2>/dev/null | awk '{print $2, $4, $8}' | sort | awk -v target="2f4b20" '{
  addr=$1; type=$2; name=$3
  val=strtonum("0x"addr)
  tgt=strtonum("0x"target)
  if (val <= tgt && val > 0) {last_name=name; last_addr=addr; last_type=type}
  if (val > tgt && !done) {print "Before: " last_name " (" last_type ") @ 0x" last_addr; print "After: " name " (" type ") @ 0x" addr; done=1}
}'

